const given = (value: string | undefined, fallback: string): string =>
  value === undefined || value === "" ? fallback : value;

const maybe = <T,>(value: string | undefined, as: (v: string) => T): T | undefined =>
  value === undefined || value === "" ? undefined : as(value);

